<template><div><PageHeader title="Batches" description="Schedule and operate cohorts from enrollment to completion."><template #actions><RouterLink class="btn primary" to="/app/batches/create">+ Create batch</RouterLink></template></PageHeader><div class="card"><div class="toolbar"><div class="toolbar-left"><input v-model="q" class="input search-input" placeholder="Search batches..."><select v-model="status" class="select"><option value="all">All status</option><option>active</option><option>planned</option><option>completed</option></select></div><div class="section-note">{{filtered.length}} batches</div></div><DataTable :headers="['Batch','Course','Trainer','Dates','Learners','Status','']" :actions="true"><tr v-for="b in filtered" :key="b.id"><td><div><strong>{{b.name}}</strong><div class="section-note">{{b.code}}</div></div></td><td>{{b.course}}</td><td>{{b.trainer}}</td><td>{{b.start}} → {{b.end}}</td><td>{{b.learners}} / {{b.capacity}}</td><td><StatusBadge :status="b.status"/></td><td><button class="btn secondary small">Open</button></td></tr></DataTable></div></div></template>
<script setup lang="ts">import {computed,ref} from 'vue';import PageHeader from '../components/PageHeader.vue';import DataTable from '../components/DataTable.vue';import StatusBadge from '../components/StatusBadge.vue';import {batches} from '../data/mock';const q=ref(''),status=ref('all');const filtered=computed(()=>batches.filter(b=>(status.value==='all'||b.status===status.value)&&`${b.name} ${b.code} ${b.course} ${b.trainer}`.toLowerCase().includes(q.value.toLowerCase())))</script>
